int
print_ip6_rthdr(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
	struct ip6_rthdr *rth = (struct ip6_rthdr *)bp;
	u_int len = rth->ip6r_len;
	int hdrlen = len * 8;
	const u_char *ep = bp + len * 8;
	int i;

	ND_PRINT((ndo, "routing header: type %u, length %u, segments left %u",
	          rth->ip6r_segleft, len, rth->ip6r_segleft));

	switch (rth->ip6r_type) {
	case 0: /* IPv6 routing header type 0 */
		ND_PRINT((ndo, ", address count %u", rth->ip6r_segleft));
		for (i = 0; i <= rth->ip6r_segleft; i++) {
			if (bp + sizeof(struct in6_addr) > ep) {
				ND_PRINT((ndo, "\n\t\t[truncated]"));
				return -1;
			}
			ND_TTEST2(*bp, sizeof(struct in6_addr));
			if (ndo->ndo_vflag <= 1 && ND_TTEST(*bp, sizeof(struct in6_addr))) {
				ND_PRINT((ndo, "\n\t\t%u: %s", i, ip6addr_string(ndo, (const uint8_t *)bp)));
			}
			bp += sizeof(struct in6_addr);
		}
		break;
	default:
		ND_PRINT((ndo, " (unknown type)"));
		break;
	}

	return hdrlen;
}

int
print_ip6_routing(struct netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
        const struct ip6_hbh *nh;
        int hl;
        uint8_t tmp;

        nh = (const struct ip6_hbh *)bp;
        ND_PRINT("Routing header");
        if (ndo->ndo_vflag < 1)
                return (-1);

        if (nh == NULL || nh->ip6h_len == 0)
                return (-1);

        hl = nh->ip6h_len * 8;
        ND_PRINT("\n\tLength: %d bytes", hl);
        ND_PRINT("\n\tType: %d", nh->ip6h_type);

        if (bp + hl > ndo->ndo_snapend)
                return (-1);

        switch (nh->ip6h_type) {
        case 0:
                if (hl < sizeof(*nh))
                        return (-1);
                tmp = nh->ip6h_segleft;
                ND_PRINT("\n\tSegments left: %d", tmp);
                break;
        default:
                ND_PRINT("\n\t(unknown routing type)");
        }

        return (hl);
}

int
ipv6_print_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rh;
    int i, len, hdrlen, off;
    u_int nh;

    rh = (const struct ip6_rthdr *)bp;
    hdrlen = (rh->ip6r_len << 3) + sizeof(struct ip6_rthdr);
    if (bp + hdrlen > ndo->ndo_snapend) {
        ND_PRINT((ndo, " [truncated]"));
        return (-1);
    }

    ND_PRINT((ndo, "Routing header (type %u, len %u, %u segments left)",
              rh->ip6r_type, rh->ip6r_len << 3, rh->ip6r_segleft));

    switch (rh->ip6r_type) {
    case 0:
        len = 0;
        off = 0;
        for (i = 0; i <= rh->ip6r_segleft; i++) {
            if (bp + sizeof(struct in6_addr) > ndo->ndo_snapend) {
                ND_PRINT((ndo, " [truncated]"));
                return (-1);
            }
            ND_PRINT((ndo, "\n    %s", ip6addr_string(ndo, (const u_char *)bp + off)));
            len += sizeof(struct in6_addr);
            off += sizeof(struct in6_addr);
        }
        break;
    default:
        ND_PRINT((ndo, " (unknown type)"));
        break;
    }

    return (hdrlen);
}

int
print_ip6_rthdr(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rth = (const struct ip6_rthdr *)bp;
    const u_char *ep = ndo->ndo_snapend;
    int len = rth->ip6r_len * 8;
    int i;

    ND_PRINT((ndo, "Routing Header: "));

    if (bp + len > ep) {
        ND_PRINT((ndo, "[|truncated]"));
        return -1;
    }

    ND_PRINT((ndo, "type %d, length %d, segments left %d",
              rth->ip6r_type, rth->ip6r_len * 8, rth->ip6r_segleft));

    switch (rth->ip6r_type) {
        case 0: /* IPv6 RH0 */
            ND_PRINT((ndo, " (RH0: Type 0)"));
            break;
        case 2: /* IPv6 RH2 */
            ND_PRINT((ndo, " (RH2: Type 2)"));
            break;
        default:
            ND_PRINT((ndo, " (Reserved Type)"));
            break;
    }

    ND_PRINT((ndo, ", Addresses:\n"));

    for (i = 0; i <= rth->ip6r_segleft; i++) {
        ND_PRINT((ndo, "  %s\n", ip6addr_string(ndo, bp + sizeof(*rth) + i * 16)));
    }

    return len;
}

int
print_ip6_rthdr(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
        const struct ip6_rthdr *rthdr = (const struct ip6_rthdr *)bp;
        const u_char *ep = ndo->ndo_snapend;
        int i, len;

        ND_PRINT("Routing header: type %u, segments left %u, length %u bytes\n",
                rthdr->ip6r_type, rthdr->ip6r_segleft, rthdr->ip6r_len * 8);

        len = sizeof(struct ip6_rthdr);

        switch (rthdr->ip6r_type) {
        case 0: /* IPv6 RHF_RH0 */
                for (i = 0; i <= rthdr->ip6r_segleft; i++) {
                        if (bp + len + sizeof(struct in6_addr) > ep)
                                goto trunc;
                        ND_PRINT("  Address %d: %s\n", i,
                                ip6addr_string(ndo, (const struct in6_addr *)(bp + len + i * sizeof(struct in6_addr))));
                }
                len += (rthdr->ip6r_segleft + 1) * sizeof(struct in6_addr);
                break;
        default:
                ND_PRINT("  (Unrecognized routing header type %u)\n", rthdr->ip6r_type);
                break;
        }

        return len;

trunc:
        ND_PRINT("[|truncated]");
        return -1;
}
